def hint(ht):
    if ht <= 2:   #Applicable only when heart is less than 3
        c = sw.count("?")
        if c > 1:  #and when player have more than one letter to guess
            hint = input("\nDO YOU WANT A HINT???? ")
            if hint in ["YES","yes","Yes","y","Y"]:
                z = 0
                while z < len(sw):
                    for p in sw:
                        if p == "?":   #gives hint if the first letter is not guessed and so on
                            sw[z] = s[z]
                            z = z + 1
                            return sw
                        elif p != "?": #it moves on to the next letter to provide hint if first letter already guessed and so on
                            z = z + 1
            elif hint in ["NO","no","No","n","N"]:
                return("")
            else:
                return("")
        else:
            return("")
    else:
        return ("")

def leaderboard(n, r):
    import csv

    data = {}

    try:
        with open("wordguess.csv", "r", newline="") as f:
            reader = csv.reader(f)

            for row in reader:
                if not row or row[0] == "Name":
                    continue

                name = row[0]

                if name not in data:
                    data[name] = [0, 0]

                # Old format: Name, won/lost
                if len(row) == 2:
                    if row[1].lower() == "won":
                        data[name][0] += 1
                    elif row[1].lower() == "lost":
                        data[name][1] += 1

                # New format: Name, wins, losses
                elif len(row) >= 3:
                    data[name][0] += int(row[1])
                    data[name][1] += int(row[2])

    except FileNotFoundError:
        pass

    if n not in data:
        data[n] = [0, 0]

    if r == 1:
        data[n][0] += 1
    else:
        data[n][1] += 1

    with open("wordguess.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["Name", "Wins", "Losses"])

        for name, scores in data.items():
            w.writerow([name, scores[0], scores[1]])
            
